/* Question bank.
   t  = subtopic id
   ty = "mcq" (auto marked) or "txt" (self marked against the mark scheme)
   o  = options, a = index of correct option (mcq) or model answer (txt)
   pts= mark scheme points, m = marks, e = explanation
*/

window.QUESTIONS = [

/* ---------- 1.1 Number systems ---------- */
{t:"1.1",ty:"mcq",m:1,q:"What is the denary value of the 8-bit binary number 1001 0110?",o:["150","148","166","134"],a:0,e:"128 + 16 + 4 + 2 = 150."},
{t:"1.1",ty:"mcq",m:1,q:"What is 202 in 8-bit binary?",o:["1100 1010","1100 0110","1101 0010","1010 1100"],a:0,e:"202 = 128 + 64 + 8 + 2, so the 128, 64, 8 and 2 columns are set."},
{t:"1.1",ty:"mcq",m:1,q:"Convert the hexadecimal number 3F to denary.",o:["63","45","61","79"],a:0,e:"(3 x 16) + 15 = 48 + 15 = 63."},
{t:"1.1",ty:"mcq",m:1,q:"Convert 1110 0101 to hexadecimal.",o:["E5","5E","D5","EB"],a:0,e:"Split into nibbles: 1110 = E and 0101 = 5, giving E5."},
{t:"1.1",ty:"mcq",m:1,q:"An 8-bit register holds 0011 1010. After a logical left shift of 2 places it holds:",o:["1110 1000","0000 1110","1010 0011","0111 0100"],a:0,e:"Every bit moves 2 places left and zeros fill in from the right. The value 58 becomes 232, which is 58 x 4."},
{t:"1.1",ty:"mcq",m:1,q:"Which statement about a logical right shift of 3 places is correct?",o:["It divides the number by 8","It multiplies the number by 8","It divides the number by 3","It reverses the order of the bits"],a:0,e:"A right shift of n places divides by 2 to the power n, and 2^3 = 8."},
{t:"1.1",ty:"mcq",m:1,q:"In 8-bit two's complement, what does 1111 0000 represent?",o:["-16","-15","240","-112"],a:0,e:"-128 + 64 + 32 + 16 = -16."},
{t:"1.1",ty:"mcq",m:1,q:"What is -35 in 8-bit two's complement?",o:["1101 1101","1010 0011","1101 1100","0010 0011"],a:0,e:"35 = 0010 0011. Flip to 1101 1100, then add 1 to get 1101 1101."},
{t:"1.1",ty:"mcq",m:1,q:"Adding 1101 1100 and 0110 0011 in an 8-bit register causes:",o:["An overflow, because the result needs 9 bits","No problem, the result is 0011 1111","A logical shift","A parity error"],a:0,e:"220 + 99 = 319, which is greater than 255, so it cannot be stored in 8 bits and the carry is lost."},
{t:"1.1",ty:"txt",m:3,q:"Explain what is meant by an overflow error and why it occurs.",a:"An overflow happens when the result of a calculation is too large to be stored in the number of bits available in the register. The extra carry bit has nowhere to be stored so it is lost, which means the value stored is incorrect. For example, in an 8-bit register the largest value is 255, so 200 + 100 cannot be represented.",pts:["The result of the calculation needs more bits than the register can hold","The carry out of the most significant bit is lost","The value stored is therefore incorrect","A valid numerical example, such as 8 bits holding a maximum of 255"]},
{t:"1.1",ty:"txt",m:2,q:"Give two reasons why hexadecimal is used to represent binary values.",a:"Hexadecimal is much shorter than the equivalent binary, so it is easier for a person to read and write, and it is less likely that a mistake is made when copying a value. Each hex digit maps directly onto four bits so conversion is straightforward.",pts:["It is shorter than binary","It is easier for a human to read and understand","There is less chance of making an error when writing it down","One hex digit represents exactly four bits, so conversion is easy"]},

/* ---------- 1.2 Text, sound, images ---------- */
{t:"1.2",ty:"mcq",m:1,q:"Which statement about ASCII and Unicode is correct?",o:["Unicode can represent many more characters than ASCII but uses more bits per character","ASCII can represent more characters than Unicode","Unicode uses fewer bits per character than ASCII","They both use exactly 8 bits per character"],a:0,e:"ASCII uses 7 bits for 128 characters. Unicode uses 16 or more bits and covers over 100,000 characters, so files are larger."},
{t:"1.2",ty:"mcq",m:1,q:"In ASCII the code for 'A' is 65. What is the code for 'D'?",o:["68","69","67","97"],a:0,e:"ASCII codes for letters run in order, so D is three after A: 65 + 3 = 68."},
{t:"1.2",ty:"mcq",m:1,q:"Increasing the sample resolution of a sound recording will:",o:["Increase the accuracy of each sample and increase the file size","Increase the number of samples taken each second","Decrease the file size","Have no effect on quality"],a:0,e:"Sample resolution is the bits per sample, so more bits means each amplitude is recorded more precisely, and the file gets bigger."},
{t:"1.2",ty:"mcq",m:1,q:"An image is 500 x 400 pixels with a colour depth of 8 bits. What is its file size in kibibytes?",o:["195.3 KiB","1562.5 KiB","200 KiB","24.4 KiB"],a:0,e:"500 x 400 x 8 = 1,600,000 bits. Divide by 8 for 200,000 bytes, then by 1024 to get 195.3 KiB."},
{t:"1.2",ty:"mcq",m:1,q:"A colour depth of 4 bits allows how many different colours?",o:["16","4","8","256"],a:0,e:"2 to the power 4 = 16."},
{t:"1.2",ty:"txt",m:3,q:"Describe how an analogue sound wave is stored in a computer.",a:"The amplitude of the sound wave is measured at regular time intervals, which is called sampling. Each measurement is converted to a binary value by an analogue to digital converter and stored. The sample rate is the number of samples per second and the sample resolution is the number of bits used for each sample.",pts:["The amplitude of the wave is measured at regular intervals (sampling)","Each sample is converted into a binary value","An analogue to digital converter is used","Sample rate is samples per second, sample resolution is bits per sample"]},
{t:"1.2",ty:"txt",m:4,q:"A photographer increases the resolution and colour depth of the images her camera produces. Explain the effects of this change.",a:"Increasing the resolution means more pixels are used, and increasing the colour depth means more bits are used for each pixel, so more shades can be shown. Together these give a more detailed and more accurate image. However the file size increases significantly, so fewer images fit on the memory card, they take longer to transfer and upload, and they need more processing power to edit.",pts:["More pixels and more bits per pixel","Better quality: more detail and more colours available","Larger file size","Consequence of larger files, such as less storage capacity, slower transfer or more processing needed"]},

/* ---------- 1.3 Storage and compression ---------- */
{t:"1.3",ty:"mcq",m:1,q:"How many bytes are in 1 mebibyte?",o:["1 048 576","1 000 000","1024","1 073 741 824"],a:0,e:"1 MiB = 1024 KiB = 1024 x 1024 bytes = 1,048,576 bytes."},
{t:"1.3",ty:"mcq",m:1,q:"Which type of file must be compressed using a lossless method?",o:["A spreadsheet of financial records","A photograph for a website","A song for streaming","A video for a social media post"],a:0,e:"Financial data must be restored exactly, so no data can be discarded."},
{t:"1.3",ty:"mcq",m:1,q:"Run length encoding replaces WWWWBBBWW with:",o:["4W3B2W","W4B3W2","WBW432","4W3B2"],a:0,e:"RLE records the count followed by the repeated value for each run."},
{t:"1.3",ty:"txt",m:4,q:"Explain the difference between lossy and lossless compression, giving one suitable use of each.",a:"Lossy compression permanently removes data that the user is unlikely to notice, such as sound frequencies outside human hearing, so the original file cannot be restored. It gives a much smaller file and is suitable for streaming music. Lossless compression reduces the file size by recording repeated patterns rather than removing data, so the original file can be restored exactly. It is suitable for text documents or program code where every character matters.",pts:["Lossy permanently removes data and the original cannot be restored","Lossless removes no data and the original can be restored exactly","A valid lossy use, such as streaming music, photos or video","A valid lossless use, such as text, spreadsheets or program code"]},
{t:"1.3",ty:"txt",m:2,q:"Give two reasons why a file might be compressed before being sent as an email attachment.",a:"The file is smaller so it uploads and downloads more quickly and uses less bandwidth. It may also be under the maximum attachment size the email service allows.",pts:["Smaller file size","Faster to send, upload or download","Uses less bandwidth","Fits within the email attachment size limit"]},

/* ---------- 2.1 Transmission ---------- */
{t:"2.1",ty:"mcq",m:1,q:"Which of these is stored in a packet header?",o:["The IP address of the receiving device","The end of packet marker","A checksum for error detection","The payload data"],a:0,e:"The header holds the sender and receiver IP addresses, the packet number and the total number of packets. The trailer holds the end marker and error checking."},
{t:"2.1",ty:"mcq",m:1,q:"Why is serial transmission normally used over long distances rather than parallel?",o:["Parallel transmission suffers from skew, where bits arrive at different times","Serial transmission sends more bits at once","Parallel cables are always full-duplex","Serial transmission does not need error checking"],a:0,e:"Over long distances the wires in a parallel cable cause bits to arrive at slightly different times, corrupting the data."},
{t:"2.1",ty:"mcq",m:1,q:"A walkie-talkie allows data to travel in both directions but only one at a time. This is:",o:["Half-duplex","Simplex","Full-duplex","Parallel"],a:0,e:"Half-duplex means both directions are possible but not simultaneously."},
{t:"2.1",ty:"mcq",m:1,q:"Which is an advantage of USB?",o:["The connector only fits one way, so it cannot be connected incorrectly","Cables can be up to 100 m long","It transmits data in parallel","It does not need a device driver of any kind"],a:0,e:"USB is a standardised serial connection, automatically detected, and the connector is designed so it cannot be inserted the wrong way. Standard cable length is limited to about 5 m."},
{t:"2.1",ty:"txt",m:4,q:"Describe how packet switching is used to send a large file across the internet.",a:"The file is split into packets of equal size. Each packet is given a header containing the sender and receiver IP addresses and the packet number. Each packet travels independently and routers choose the fastest available route for each one, so packets may take different paths and arrive out of order. At the destination the packets are reordered using their packet numbers, and any packet that is missing is requested again before the file is reassembled.",pts:["The data is split into packets","Each packet has a header with addresses and a packet number","Packets travel independently and routers choose the best route for each","Packets may arrive out of order and are reordered at the destination","Missing packets are requested again"]},

/* ---------- 2.2 Error detection ---------- */
{t:"2.2",ty:"mcq",m:1,q:"A system uses even parity. Which byte contains an error?",o:["1101 1010","1100 1100","0000 0000","1111 0000"],a:0,e:"1101 1010 contains five 1s, which is odd, so it fails an even parity check. The other three each contain an even number of 1s (four, zero and four)."},
{t:"2.2",ty:"mcq",m:1,q:"What is the main limitation of a single parity check?",o:["If two bits are changed the parity may still be correct, so the error is missed","It cannot be used with binary data","It requires the data to be sent twice","It only works for text files"],a:0,e:"Two errors can cancel each other out, and a parity bit also cannot say which bit was wrong."},
{t:"2.2",ty:"mcq",m:1,q:"A check digit is mainly used to detect errors made during:",o:["Data entry","Data transmission over a network","Data encryption","Data compression"],a:0,e:"Check digits are calculated from the other digits of a number such as a barcode or ISBN and detect typing or scanning errors."},
{t:"2.2",ty:"txt",m:4,q:"Describe how an automatic repeat request (ARQ) makes sure data is received correctly.",a:"The receiving device uses an error detection method such as a checksum to check each packet. If the data is correct a positive acknowledgement is sent back to the sender. If an error is found a negative acknowledgement is sent and the data is retransmitted. The sender also starts a timer when it sends data, and if no acknowledgement is received before the timeout expires the data is automatically sent again. This repeats until the data arrives correctly or a set limit of attempts is reached.",pts:["The receiver checks the data for errors","A positive acknowledgement is sent if the data is correct","A negative acknowledgement causes retransmission","A timeout is used, and data is resent if no acknowledgement arrives","The process repeats until correct or a limit is reached"]},
{t:"2.2",ty:"txt",m:3,q:"Describe how a checksum is used to detect errors in transmitted data.",a:"Before sending, the sender puts the block of data through an algorithm which calculates a checksum value, and this value is sent with the data. When the data arrives, the receiver runs the same algorithm on the data it received to calculate its own checksum. The two values are compared, and if they are different an error has occurred during transmission, so a resend is requested.",pts:["The sender calculates a checksum from the data using an algorithm","The checksum is sent with the data","The receiver recalculates the checksum using the same algorithm","The two values are compared and a difference means an error, so the data is resent"]},

/* ---------- 2.3 Encryption ---------- */
{t:"2.3",ty:"mcq",m:1,q:"What is the purpose of encryption?",o:["To make intercepted data meaningless without the key","To stop data being intercepted at all","To reduce the size of the data being sent","To detect errors in transmitted data"],a:0,e:"Encryption does not prevent interception. It makes stolen data impossible to understand without the correct decryption key."},
{t:"2.3",ty:"mcq",m:1,q:"In asymmetric encryption, which key is used to encrypt a message being sent to Amira?",o:["Amira's public key","Amira's private key","The sender's private key","A shared symmetric key"],a:0,e:"You encrypt with the recipient's public key, so only their matching private key can decrypt it."},
{t:"2.3",ty:"txt",m:3,q:"Explain why asymmetric encryption is considered more secure than symmetric encryption.",a:"In symmetric encryption the same key is used to encrypt and decrypt, so the key must also be sent to the recipient. If the key is intercepted during transmission the whole message can be read. In asymmetric encryption there is a key pair: the public key can be shared freely and is used to encrypt, but the private key that decrypts the data is never transmitted and is known only to its owner, so there is no key for an attacker to intercept.",pts:["Symmetric uses one key for both encryption and decryption","That key must be transmitted, so it can be intercepted","Asymmetric uses a public key to encrypt and a private key to decrypt","The private key is never transmitted, so it cannot be intercepted"]},

/* ---------- 3.1 Architecture ---------- */
{t:"3.1",ty:"mcq",m:1,q:"Which register holds the address of the next instruction to be fetched?",o:["Program counter","Memory data register","Accumulator","Current instruction register"],a:0,e:"The PC holds the address of the next instruction. The MAR holds the address currently being accessed."},
{t:"3.1",ty:"mcq",m:1,q:"Which component performs calculations and logical comparisons?",o:["The arithmetic logic unit","The control unit","The memory address register","The address bus"],a:0,e:"The ALU carries out all arithmetic and logic, storing results in the accumulator."},
{t:"3.1",ty:"mcq",m:1,q:"The address bus is described as unidirectional because:",o:["Addresses only travel from the CPU to memory","Data can only be read, never written","It carries only control signals","It has fewer wires than the data bus"],a:0,e:"Addresses are always sent out by the CPU, whereas data travels both ways on the bidirectional data bus."},
{t:"3.1",ty:"mcq",m:1,q:"A computer with four cores does not run four times faster than a single-core machine because:",o:["Software must be written to make use of multiple cores","The cores share one program counter","Extra cores reduce the clock speed to a quarter","Only one core has access to cache"],a:0,e:"Parallel processing only helps if the software is written to split work across cores."},
{t:"3.1",ty:"mcq",m:1,q:"Which is the best description of an embedded system?",o:["Hardware and software built to perform one specific function within a larger device","Any computer with less than 4 GB of RAM","A computer that has no operating system at all","A network of small computers working together"],a:0,e:"Examples include washing machines, traffic lights and engine management systems."},
{t:"3.1",ty:"txt",m:5,q:"Describe the fetch stage of the fetch, decode, execute cycle, naming the registers used.",a:"The address of the next instruction is copied from the program counter into the memory address register. The program counter is then incremented by one so it points to the following instruction. The instruction stored at the address in the MAR is fetched from memory and travels along the data bus into the memory data register. It is then copied from the MDR into the current instruction register, ready to be decoded.",pts:["The address in the PC is copied to the MAR","The PC is incremented by 1","The instruction at that address is fetched from memory","It travels along the data bus into the MDR","The instruction is copied from the MDR into the CIR"]},
{t:"3.1",ty:"txt",m:4,q:"Explain how increasing cache size can improve the performance of a computer.",a:"Cache is very fast memory located in or very close to the CPU that stores frequently used instructions and data. When the CPU needs data it checks the cache first, and if the data is there it can be accessed much more quickly than fetching it from RAM. A larger cache means more instructions and data can be held, so there are more cache hits and fewer slow trips to RAM, which means the CPU spends less time waiting and more instructions are processed each second.",pts:["Cache stores frequently used instructions and data","Cache is much faster to access than RAM","A larger cache holds more data, so more requests are met from cache","Fewer accesses to slower RAM are needed, so the CPU waits less"]},
{t:"3.1",ty:"txt",m:2,q:"State the difference between the memory address register and the memory data register.",a:"The MAR stores the address of the memory location that is currently being read from or written to. The MDR stores the actual data or instruction that has been fetched from that location, or that is about to be written to it.",pts:["The MAR holds an address of a memory location","The MDR holds the data or instruction itself"]},

/* ---------- 3.2 I/O devices ---------- */
{t:"3.2",ty:"mcq",m:1,q:"A greenhouse system needs to detect how wet the soil is. Which sensor is appropriate?",o:["Moisture sensor","Pressure sensor","Light sensor","Proximity sensor"],a:0,e:"A moisture sensor measures water content in the soil."},
{t:"3.2",ty:"mcq",m:1,q:"Why is an analogue to digital converter needed between a sensor and a microprocessor?",o:["Sensor readings are analogue and the microprocessor can only process digital data","It amplifies the signal so it travels further","It converts the microprocessor's output into movement","It checks the sensor reading for errors"],a:0,e:"Physical quantities are continuous, so an ADC is required to turn them into binary."},
{t:"3.2",ty:"mcq",m:1,q:"Which device is an actuator?",o:["A motor that opens a window","A temperature sensor","A barcode scanner","An LCD screen"],a:0,e:"An actuator creates physical movement, such as a motor, pump or valve."},
{t:"3.2",ty:"txt",m:3,q:"Describe how a barcode scanner reads a barcode.",a:"A light source such as a laser or LED is shone at the barcode. The black bars absorb light and the white spaces reflect it, so the amount of reflected light differs. A sensor measures the reflected light and the pattern is converted into a binary number, which is then used to look up the product in a database.",pts:["Light is shone onto the barcode","Black bars absorb light and white spaces reflect it","A sensor detects the amount of light reflected","The pattern is converted into a binary value or number"]},

/* ---------- 3.3 Storage ---------- */
{t:"3.3",ty:"mcq",m:1,q:"Which statement about RAM and ROM is correct?",o:["RAM is volatile and ROM is non-volatile","ROM is volatile and RAM is non-volatile","Both are volatile","Both can be freely written to by the user"],a:0,e:"RAM loses its contents when power is removed. ROM keeps its contents and stores start-up instructions."},
{t:"3.3",ty:"mcq",m:1,q:"How does solid state storage hold data?",o:["Electrons are trapped on floating gates in NAND flash memory","Areas of a spinning platter are magnetised","A laser burns pits into a reflective surface","Data is stored as sound waves"],a:0,e:"Solid state storage uses transistors as control and floating gates, with no moving parts."},
{t:"3.3",ty:"mcq",m:1,q:"What happens when RAM becomes full and virtual memory is used?",o:["Data from programs not currently in use is moved from RAM to secondary storage","The computer immediately shuts down","ROM is used as extra RAM","The clock speed of the CPU is increased"],a:0,e:"Inactive pages are moved to a reserved area of the hard disk, freeing RAM for the active program."},
{t:"3.3",ty:"txt",m:4,q:"A company is replacing the hard disk drives in its laptops with solid state drives. Give two advantages and two disadvantages of this change.",a:"Advantages: solid state drives have no moving parts so they are much faster to read and write and start up more quickly, and they are far more durable so are less likely to be damaged if a laptop is dropped. They also use less power, extending battery life, and are silent. Disadvantages: they are more expensive per gigabyte, so the same budget buys less capacity, and they have a limited number of read and write cycles before the memory wears out.",pts:["Advantage: faster access because there are no moving parts","Advantage: more durable, lower power use, lighter or silent","Disadvantage: higher cost per gigabyte","Disadvantage: limited number of read and write cycles"]},
{t:"3.3",ty:"txt",m:4,q:"Explain two advantages and two disadvantages of storing company data in cloud storage.",a:"Advantages: the data can be accessed from any device anywhere with an internet connection, which suits staff working remotely, and the provider handles backups and maintenance so the company does not need its own server hardware or IT staff for it. Storage can also be scaled up as needed. Disadvantages: an internet connection is essential, so no work can be done if it fails, and the company must trust a third party with confidential data, which could be exposed by a breach at the provider. There are also ongoing subscription costs.",pts:["Advantage: access from anywhere with an internet connection","Advantage: the provider handles backup, maintenance or scalability","Disadvantage: requires an internet connection with sufficient bandwidth","Disadvantage: security or privacy depends on a third party, or ongoing costs"]},

/* ---------- 3.4 Network hardware ---------- */
{t:"3.4",ty:"mcq",m:1,q:"Which statement about a MAC address is correct?",o:["It is set by the manufacturer and identifies the device's hardware","It is assigned by the network and changes when the device moves network","It is 32 bits long and written in denary","It is used by DNS servers to find websites"],a:0,e:"A MAC address is 48 bits, written as 12 hex digits, and identifies the hardware rather than its location."},
{t:"3.4",ty:"mcq",m:1,q:"In the MAC address 00-1C-B3-4F-25-FE, what does 4F-25-FE represent?",o:["The serial number of the device","The manufacturer identifier","The subnet mask","The IP address in hexadecimal"],a:0,e:"The first six hex digits identify the manufacturer, the last six are the device's serial number."},
{t:"3.4",ty:"mcq",m:1,q:"Why was IPv6 introduced?",o:["IPv4 addresses were running out because there are only about 4 billion","IPv6 is shorter and easier to type","IPv4 cannot be used with routers","IPv6 removes the need for MAC addresses"],a:0,e:"IPv6 uses 128 bits rather than 32, providing vastly more addresses."},
{t:"3.4",ty:"txt",m:2,q:"Give one advantage of a device having a static IP address rather than a dynamic one.",a:"A static IP address never changes, so the device can always be found at the same address. This is essential for a web server or for setting up remote access to a computer.",pts:["The address never changes","The device can always be located, for example for a website or remote access"]},

/* ---------- 4.1 Software and interrupts ---------- */
{t:"4.1",ty:"mcq",m:1,q:"Which of these is system software?",o:["A device driver","A spreadsheet program","A web browser","A photo editor"],a:0,e:"System software manages the hardware. Device drivers, the OS, utilities and compilers are all system software."},
{t:"4.1",ty:"mcq",m:1,q:"What does disk defragmentation software do?",o:["Rearranges files so each is stored in contiguous sectors","Deletes files that have not been used recently","Compresses files so they take less space","Scans files for viruses"],a:0,e:"Defragmentation reduces head movement by putting the parts of each file together, speeding up access."},
{t:"4.1",ty:"mcq",m:1,q:"Which of these would generate a hardware interrupt?",o:["A printer running out of paper","A division by zero in a program","A syntax error found by the compiler","A logic error in a loop"],a:0,e:"Hardware interrupts come from devices. Division by zero is a software interrupt."},
{t:"4.1",ty:"txt",m:4,q:"Describe what happens when the CPU receives an interrupt.",a:"At the end of the current fetch, decode, execute cycle the CPU checks for interrupt signals. The contents of the registers for the current job are saved onto a stack so the job can be resumed later. The CPU then loads and runs the appropriate interrupt service routine to deal with the request. When the routine has finished, the saved register values are restored from the stack and the original job continues from exactly where it left off. If a higher priority interrupt arrives, it can interrupt a lower priority one.",pts:["The CPU checks for interrupts at the end of the current FDE cycle","The current job's register contents are saved onto a stack","The relevant interrupt service routine is run","The saved values are restored and the original job resumes","Interrupts have priorities"]},
{t:"4.1",ty:"txt",m:3,q:"Explain the purpose of a device driver.",a:"A device driver is system software that allows the operating system to communicate with a particular piece of hardware. It translates the general instructions from the operating system into the specific commands that device understands. Each type of device needs its own driver, and without the correct driver the hardware will not work properly.",pts:["It allows the operating system to communicate with hardware","It translates OS instructions into commands the device understands","Each device needs its own specific driver, or the device will not work without it"]},

/* ---------- 4.2 Languages and translators ---------- */
{t:"4.2",ty:"mcq",m:1,q:"Which statement about compilers and interpreters is correct?",o:["A compiler produces an executable file, an interpreter does not","An interpreter produces an executable file, a compiler does not","Both produce an executable file","Neither can report errors"],a:0,e:"Once compiled the program can be run without the compiler. An interpreter must be present every time."},
{t:"4.2",ty:"mcq",m:1,q:"Why might a programmer prefer an interpreter while developing a program?",o:["It stops at the first error, making errors easier to find and fix one at a time","The finished program runs faster","It hides the source code from the user","It translates the whole program before running it"],a:0,e:"Line by line execution reports errors as they are reached, which suits development and testing."},
{t:"4.2",ty:"mcq",m:1,q:"An advantage of a high-level language over a low-level language is that it is:",o:["Portable, so it can run on different types of computer","Directly executable without any translation","Always faster to execute","Written specifically for one instruction set"],a:0,e:"High-level languages are machine independent as long as a suitable translator exists."},
{t:"4.2",ty:"txt",m:4,q:"Describe two features of an integrated development environment that help a programmer find and correct errors.",a:"Breakpoints let the programmer mark a line where the program will pause during execution, so they can inspect the state of the program at that exact point and see whether the values are as expected. A variable watch window displays the current value of chosen variables and updates as the program runs, so the programmer can see the moment a variable takes an unexpected value. Error diagnostics also highlight the line containing an error and give a description of the problem.",pts:["Breakpoint named","Breakpoint explained: pauses execution at a chosen line so the program can be inspected","Second feature named, such as variable watch window, single stepping or error diagnostics","Second feature explained correctly"]},

/* ---------- 5.1 Internet and WWW ---------- */
{t:"5.1",ty:"mcq",m:1,q:"Which statement correctly distinguishes the internet from the World Wide Web?",o:["The internet is the network infrastructure, the web is the collection of websites accessed using it","The web is the network infrastructure, the internet is the collection of websites","They are two names for exactly the same thing","The internet only carries email, the web carries everything else"],a:0,e:"The internet is hardware and protocols. The web is the content carried over it."},
{t:"5.1",ty:"mcq",m:1,q:"What is the main purpose of a DNS server?",o:["To translate a domain name into an IP address","To store copies of web pages for faster access","To encrypt data sent to a website","To block traffic that does not meet its criteria"],a:0,e:"Caching is a proxy server, blocking traffic is a firewall, and encryption is SSL."},
{t:"5.1",ty:"mcq",m:1,q:"Which cookie is deleted as soon as the browser is closed?",o:["A session cookie","A persistent cookie","A tracking cookie","A secure cookie"],a:0,e:"Session cookies are held in memory only. Persistent cookies are stored on the hard disk."},
{t:"5.1",ty:"txt",m:5,q:"Describe the steps taken by a browser to display a web page after the user types a URL.",a:"The browser sends the domain name from the URL to the nearest DNS server. If that server holds the matching IP address it returns it to the browser. If it does not, the request is passed on to another DNS server higher up until the IP address is found, or an error is returned if the domain does not exist. The browser then sends a request directly to the web server at that IP address. The web server returns the HTML for the page, and the browser renders the HTML to display the page on screen.",pts:["The browser sends the domain name to a DNS server","The DNS server looks up the matching IP address","If not found, the request is passed to another DNS server","The IP address is returned to the browser","The browser requests the page from the web server at that address","The browser renders the returned HTML"]},
{t:"5.1",ty:"txt",m:3,q:"Explain why a shopping website uses HTTPS rather than HTTP.",a:"HTTPS encrypts the data sent between the browser and the web server using SSL or TLS. Customers enter personal details and payment card numbers, so if the data were intercepted while being transmitted it would be readable with HTTP. With HTTPS any intercepted data is meaningless without the decryption key. The site also has a digital certificate, shown by the padlock, which reassures the customer that the site is genuine.",pts:["HTTPS encrypts the data being transmitted","Intercepted data is meaningless without the key","Protects personal or payment data being entered","A security certificate or padlock shows the site is genuine"]},

/* ---------- 5.2 Digital currency ---------- */
{t:"5.2",ty:"mcq",m:1,q:"What is a blockchain?",o:["A digital ledger of transactions duplicated across every computer in the network","A physical chain of servers in a data centre","An encryption algorithm used by banks","A type of firewall used by cryptocurrency exchanges"],a:0,e:"Each block holds transactions, a timestamp, its own hash and the previous block's hash."},
{t:"5.2",ty:"txt",m:4,q:"Explain how a blockchain makes it very difficult to tamper with a transaction.",a:"Each block contains a hash calculated from its own contents and also stores the hash of the previous block, linking the blocks into a chain. If someone alters a transaction in a block, that block's hash changes, so it no longer matches the hash stored in the next block and the chain is broken, making the change obvious. Because the ledger is duplicated across every computer on the network, an attacker would have to make the same change to every following block on the majority of copies at the same time, which is not realistic.",pts:["Each block stores a hash of its own contents","Each block also stores the hash of the previous block","Changing a block changes its hash and breaks the link to later blocks","The ledger is copied across the whole network so every copy would need changing"]},

/* ---------- 5.3 Cyber security ---------- */
{t:"5.3",ty:"mcq",m:1,q:"Which type of malware replicates itself across a network without needing a host file or user action?",o:["Worm","Virus","Trojan horse","Adware"],a:0,e:"A virus needs a host file and usually a user action. A worm spreads by itself."},
{t:"5.3",ty:"mcq",m:1,q:"A user types the correct web address but is taken to a fake site because malicious code has changed their DNS settings. This is:",o:["Pharming","Phishing","A brute force attack","Social engineering"],a:0,e:"Pharming redirects the user without any action on their part. Phishing requires the user to click a link."},
{t:"5.3",ty:"mcq",m:1,q:"Which measure best protects against a brute force attack?",o:["Limiting the number of log-in attempts and using long complex passwords","Compressing the password file","Using a session cookie","Defragmenting the hard disk"],a:0,e:"Brute force tries every combination, so length, complexity and attempt limits are the defence."},
{t:"5.3",ty:"mcq",m:1,q:"Malware that encrypts a user's files and demands payment for the key is:",o:["Ransomware","Spyware","Adware","A worm"],a:0,e:"Ransomware holds the data hostage by encrypting it."},
{t:"5.3",ty:"txt",m:4,q:"Explain the difference between phishing and pharming.",a:"In phishing the attacker sends a message, usually an email, that appears to come from a legitimate company and contains a link to a fake website. The user must be tricked into clicking the link and entering their details, which are then captured. In pharming, malicious code is installed on the user's computer or on a DNS server, and it redirects the user to the fake website automatically even when they type the correct address themselves. The key difference is that phishing needs the user to take an action, while pharming does not.",pts:["Phishing uses a message or email containing a link to a fake site","The user must click the link and enter their details","Pharming uses malicious code on the computer or DNS server","The user is redirected automatically without taking any action"]},
{t:"5.3",ty:"txt",m:4,q:"A school wants to protect its network. Describe how a firewall and a proxy server each help.",a:"A firewall monitors the traffic entering and leaving the network and compares it against a set of criteria. Traffic that fails the criteria is blocked, and the firewall keeps a log of the traffic and can block specific IP addresses or applications, which helps prevent hacking and denial of service attacks. A proxy server acts as an intermediary between the users and the web servers, so the users' IP addresses are hidden. It can filter traffic and block access to listed websites, and it caches frequently visited pages so they load more quickly. It also takes the impact of an attack instead of the school's own web server.",pts:["A firewall monitors incoming and outgoing traffic","It blocks traffic that does not meet its criteria, and can log it","A proxy server acts as an intermediary and hides the user's IP address","A proxy can filter or block websites, and caches pages to speed up access"]},
{t:"5.3",ty:"txt",m:3,q:"Explain how two-step verification protects a user account, and why a password alone is less secure.",a:"With two-step verification the user enters their password and then a one-time code is sent to a separate device such as their phone, which must also be entered. This means that even if an attacker discovers or guesses the password, they still cannot get in without physical access to the second device. A password alone can be guessed by a brute force attack, stolen by spyware, or captured by phishing, so it is a single point of failure.",pts:["A one-time code is sent to a separate device and must also be entered","An attacker with only the password still cannot access the account","A password alone can be guessed, intercepted or stolen"]},

/* ---------- 6.1 Automated systems ---------- */
{t:"6.1",ty:"mcq",m:1,q:"In an automated system, what does the microprocessor compare the sensor reading with?",o:["A stored pre-set value","The previous reading only","The output of the actuator","The reading from a different system"],a:0,e:"The comparison against a stored pre-set value is what triggers the action."},
{t:"6.1",ty:"txt",m:5,q:"Describe how an automated system keeps a greenhouse at the correct temperature and moisture level.",a:"Temperature and moisture sensors continuously take readings inside the greenhouse and send them to the microprocessor, passing through an analogue to digital converter because sensor readings are analogue. The microprocessor compares each reading with a stored pre-set value. If the temperature is above the pre-set value, the microprocessor sends a signal to an actuator, which is a motor that opens a window. If the moisture reading is below the pre-set value, a signal is sent to an actuator to open a valve and water the plants. The process repeats continuously and no human intervention is needed.",pts:["Sensors continuously send readings to the microprocessor","An ADC converts the analogue readings to digital","The microprocessor compares each reading with a stored pre-set value","If outside the range, a signal is sent to an actuator (window motor or water valve)","The process repeats continuously without human intervention"]},

/* ---------- 6.2 Robotics ---------- */
{t:"6.2",ty:"mcq",m:1,q:"Which is a characteristic of a robot?",o:["It has programmable instructions that can be changed","It can only ever be operated remotely by a human","It never uses sensors","It cannot contain any moving parts"],a:0,e:"Robots have a mechanical structure, electrical components, sensors, actuators and programmable instructions."},
{t:"6.2",ty:"txt",m:4,q:"A car factory replaces workers on its assembly line with robots. Give two advantages and two disadvantages.",a:"Advantages: robots can work continuously 24 hours a day without breaks, holidays or wages, which raises productivity, and they carry out each task with consistent accuracy so there are fewer faults and less wasted material. They can also work safely in conditions such as paint spraying that would be hazardous to people. Disadvantages: there is a very high initial cost to buy, install and program the robots, and workers doing manual jobs lose their employment. Robots also lack flexibility, so retooling the line for a different car model is expensive and slow, and a breakdown can halt the whole production line.",pts:["Advantage: can work continuously without breaks or wages","Advantage: consistent accuracy, higher productivity or safer in hazardous conditions","Disadvantage: high initial cost of purchase, installation and programming","Disadvantage: job losses, lack of flexibility, or reliance on specialist maintenance"]},

/* ---------- 6.3 AI ---------- */
{t:"6.3",ty:"mcq",m:1,q:"Which part of an expert system applies the rules to reach a conclusion?",o:["The inference engine","The knowledge base","The user interface","The explanation system"],a:0,e:"The inference engine is the problem solving part, effectively the brain of the system."},
{t:"6.3",ty:"mcq",m:1,q:"What best describes machine learning?",o:["A system that improves its own performance automatically as it is given more data","A system that must be reprogrammed by hand to improve","A system that stores facts collected from human experts","A system that converts analogue data to digital"],a:0,e:"Machine learning improves without explicit reprogramming."},
{t:"6.3",ty:"txt",m:4,q:"Describe the components of an expert system and how they are used to give a diagnosis.",a:"The user interface asks the user a series of questions and displays the results. The knowledge base is a large store of facts gathered from human experts in that field. The rule base holds inference rules in the form IF ... THEN ... . The inference engine takes the user's answers, searches the knowledge base and applies the rules from the rule base to narrow down the possibilities and reach a conclusion. The explanation system then presents the conclusion together with the probability that it is correct and the reasoning that led to it.",pts:["User interface asks questions and shows results","Knowledge base holds facts from human experts","Rule base holds IF THEN inference rules","Inference engine applies the rules to the knowledge base to reach a conclusion","Explanation system gives the reasoning and probability"]},

/* ---------- 7.1 Life cycle ---------- */
{t:"7.1",ty:"mcq",m:1,q:"A program runs without crashing but always calculates the average as one greater than it should be. This is:",o:["A logic error","A syntax error","A run-time error","A transposition error"],a:0,e:"The program is valid code but the result is wrong, which is a logic error."},
{t:"7.1",ty:"mcq",m:1,q:"A program accepts values from 10 to 50. Which pair is boundary test data?",o:["9 and 10","25 and 30","5 and 60","10 and 50"],a:0,e:"Boundary data is a pair either side of the limit: one value that should be rejected and one that should be accepted. 10 and 50 alone are extreme data."},
{t:"7.1",ty:"mcq",m:1,q:"Which is the best definition of decomposition?",o:["Breaking a problem down into smaller sub-problems that can be solved separately","Removing details that are not needed to solve the problem","Testing a program with abnormal data","Translating a high-level language into machine code"],a:0,e:"Removing unnecessary details is abstraction."},
{t:"7.1",ty:"txt",m:4,q:"A program asks the user to enter a percentage mark between 0 and 100. Give one example each of normal, abnormal, extreme and boundary test data, and state why each is used.",a:"Normal: 57, used to check the program accepts sensible data and processes it correctly. Abnormal: 150 or the word 'seven', used to check the program rejects data that is out of range or the wrong type. Extreme: 0 and 100, used to check the values at the limits are still accepted. Boundary: 100 and 101, used to check the program accepts the last valid value and rejects the first invalid one.",pts:["Normal data with a valid value and reason","Abnormal data that should be rejected with a reason","Extreme data at the limits, still accepted","Boundary data given as a pair either side of a limit"]},

/* ---------- 7.2 Flowcharts and pseudocode ---------- */
{t:"7.2",ty:"mcq",m:1,q:"Which flowchart symbol is used for a decision?",o:["A diamond","A parallelogram","A rectangle","A rounded rectangle"],a:0,e:"A parallelogram is input or output, a rectangle is a process, a rounded rectangle is a terminator."},
{t:"7.2",ty:"mcq",m:1,q:"Which loop is guaranteed to run at least once?",o:["REPEAT ... UNTIL","WHILE ... ENDWHILE","FOR ... NEXT with a count of 0","None of them"],a:0,e:"REPEAT tests its condition after the body has run, so the body always executes at least once."},
{t:"7.2",ty:"txt",m:3,q:"State the difference between a WHILE loop and a REPEAT loop, and give a situation where a REPEAT loop is the better choice.",a:"A WHILE loop is a pre-condition loop: the condition is tested before the body runs, so if the condition is false at the start the body never runs at all. A REPEAT loop is a post-condition loop: the condition is tested after the body, so the body always runs at least once. A REPEAT loop is better when the program asks the user for a password, because the user must be prompted at least once before the input can be checked.",pts:["WHILE tests the condition before the loop body","REPEAT tests the condition after the loop body","WHILE may run zero times, REPEAT always runs at least once","A sensible example where at least one iteration is required"]},

/* ---------- 7.3 Trace tables ---------- */
{t:"7.3",ty:"mcq",m:1,q:"Trace: Total = 0; FOR i = 1 TO 5: IF i MOD 2 = 0 THEN Total = Total + i; NEXT i. What is Total?",o:["6","9","15","10"],a:0,e:"Only the even values 2 and 4 are added, giving 6."},
{t:"7.3",ty:"mcq",m:1,q:"Trace: X = 20; WHILE X > 5 DO X = X - 6; ENDWHILE. What is X when the loop ends?",o:["2","-4","8","5"],a:0,e:"20, 14, 8, 2. At 2 the condition 2 > 5 is false, so the loop stops with X = 2."},
{t:"7.3",ty:"mcq",m:1,q:"Trace: A = 3; B = 7; A = A + B; B = A - B; A = A - B. What are A and B at the end?",o:["A = 7, B = 3","A = 3, B = 7","A = 10, B = 3","A = 7, B = 7"],a:0,e:"A becomes 10, B becomes 10 - 7 = 3, then A becomes 10 - 3 = 7. This swaps the two values."},
{t:"7.3",ty:"txt",m:3,q:"An algorithm should output the average of 10 numbers but always outputs the running total instead. Suggest what the error is and how to correct it.",a:"The division by 10 has been left out, or it has been placed inside the loop rather than after it, so the value output is the total rather than the mean. The correction is to keep adding each number to the total inside the loop, then after the loop has finished divide the total by 10 (or by the counter) and output that result.",pts:["Identifies that the total is not divided by the number of values","Or that the calculation is in the wrong place, inside instead of after the loop","States the correction: divide the total by the count after the loop, then output"]},

/* ---------- 7.4 Producing algorithms ---------- */
{t:"7.4",ty:"mcq",m:1,q:"Which validation check makes sure a field has not been left empty?",o:["Presence check","Range check","Format check","Length check"],a:0,e:"A presence check confirms that data has actually been entered."},
{t:"7.4",ty:"mcq",m:1,q:"What is a rogue value used for?",o:["To signal the end of a set of input data and stop a loop","To test whether a password is correct","To store the largest value found so far","To generate random numbers"],a:0,e:"A rogue value, or sentinel, is a value outside the valid range, such as -1, used to end input."},
{t:"7.4",ty:"mcq",m:1,q:"Entering a new password twice and comparing the two entries is an example of:",o:["Verification by double entry","A range check","Validation by format check","A checksum"],a:0,e:"Verification checks the data was entered accurately, it does not check the data is sensible."},
{t:"7.4",ty:"txt",m:4,q:"Explain the difference between validation and verification, giving one example of each.",a:"Validation is an automatic check carried out by the computer to make sure the data entered is sensible and within acceptable limits, for example a range check that a month entered is between 1 and 12. Verification checks that data has been copied or entered accurately and matches the original source, for example double entry where a password is typed twice and the two entries are compared. Validation cannot prove the data is actually correct, only that it is reasonable.",pts:["Validation is an automatic check that data is sensible or within limits","A correct validation example, named and explained","Verification checks data has been entered or copied accurately","A correct verification example, such as double entry or a visual check"]},
{t:"7.4",ty:"txt",m:5,q:"Write an algorithm in pseudocode that inputs 20 temperatures, then outputs the highest, the lowest and the average.",a:"Total = 0, Highest = -100, Lowest = 100. FOR i = 1 TO 20: INPUT Temp; Total = Total + Temp; IF Temp > Highest THEN Highest = Temp ENDIF; IF Temp < Lowest THEN Lowest = Temp ENDIF; NEXT i. OUTPUT Highest, Lowest and Total / 20.",pts:["Total initialised to 0 and Highest and Lowest initialised sensibly before the loop","A count-controlled loop repeating 20 times with an INPUT inside","Running total updated inside the loop","Both comparisons to update Highest and Lowest inside the loop","Average calculated as Total / 20 after the loop, and all three values output"]},

/* ---------- 8.1 Programming concepts ---------- */
{t:"8.1",ty:"mcq",m:1,q:"What is the value of 27 MOD 4?",o:["3","6","6.75","7"],a:0,e:"MOD gives the remainder: 27 = 6 x 4 + 3, so the remainder is 3. 27 DIV 4 would be 6."},
{t:"8.1",ty:"mcq",m:1,q:"Which data type should be used to store a price such as 12.99?",o:["REAL","INTEGER","STRING","BOOLEAN"],a:0,e:"REAL stores numbers with a decimal part."},
{t:"8.1",ty:"mcq",m:1,q:"What does SUBSTRING(\"Computer\", 4, 3) return?",o:["\"put\"","\"omp\"","\"pute\"","\"put\" starting at position 3"],a:0,e:"It takes 3 characters starting at position 4, which are p, u and t."},
{t:"8.1",ty:"mcq",m:1,q:"Which statement about a function is true?",o:["It returns a single value to the part of the program that called it","It cannot be given any parameters","It can never be used more than once","It always changes a global variable"],a:0,e:"A function returns a value, a procedure does not."},
{t:"8.1",ty:"mcq",m:1,q:"Which test correctly checks whether the value in Num is even?",o:["Num MOD 2 = 0","Num DIV 2 = 0","Num / 2 = 0","Num MOD 2 = 1"],a:0,e:"An even number leaves no remainder when divided by 2."},
{t:"8.1",ty:"txt",m:3,q:"Explain why a programmer would use a constant rather than a variable for the rate of VAT.",a:"The rate of VAT does not change while the program is running, and declaring it as a constant means it cannot be altered by mistake anywhere in the code. Using a meaningful name such as VATRate also makes the program easier to read than a bare number, and if the rate ever does change it only has to be edited in one place rather than everywhere it is used.",pts:["The value does not change while the program runs","It cannot be changed accidentally by the program","It makes the program easier to read and maintain","A change only needs to be made in one place"]},
{t:"8.1",ty:"txt",m:4,q:"Explain two benefits of using procedures and functions in a large program.",a:"The code for a task is written once and can then be called from many places in the program, which avoids repeating the same code and makes the program shorter. Each subroutine can be tested on its own, so errors are easier to find, and if a change is needed it only has to be made in one place. Splitting the program into subroutines also means several programmers can work on different parts at the same time, and the program is easier to read because each subroutine has a clear name and purpose.",pts:["Code is written once and reused, avoiding repetition","Each subroutine can be tested and debugged separately","A change only has to be made in one place","The program is easier to read, or work can be split between programmers"]},
{t:"8.1",ty:"txt",m:3,q:"State one advantage of using a local variable rather than a global variable.",a:"A local variable only exists inside the subroutine where it is declared, so it cannot be changed accidentally by code elsewhere in the program. The memory it uses is also released when the subroutine finishes, and the same identifier can safely be reused in other subroutines.",pts:["It can only be accessed within its own subroutine","It cannot be changed accidentally by other parts of the program","Memory is freed when the subroutine ends, or the name can be reused elsewhere"]},

/* ---------- 8.2 Arrays ---------- */
{t:"8.2",ty:"mcq",m:1,q:"Which declaration creates a table with 4 rows and 6 columns of integers?",o:["DECLARE Grid : ARRAY[1:4, 1:6] OF INTEGER","DECLARE Grid : ARRAY[1:6, 1:4] OF INTEGER","DECLARE Grid : ARRAY[1:24] OF INTEGER","DECLARE Grid : ARRAY[4, 6] OF STRING"],a:0,e:"The first index is the row, the second is the column."},
{t:"8.2",ty:"mcq",m:1,q:"To read every element of a 2D array you need:",o:["Nested loops, an outer loop for rows and an inner loop for columns","A single FOR loop","A WHILE loop with no counter","A separate variable for every element"],a:0,e:"One loop moves through the rows and the loop inside it moves along each column of that row."},
{t:"8.2",ty:"txt",m:4,q:"Explain why an array is better than 30 separate variables for storing 30 student marks.",a:"All 30 marks are stored under one identifier, so the program is much shorter and easier to read than declaring 30 separate names. Because each mark is reached by an index, a loop can be used with the loop counter as the index to input, total or search through every mark with only a few lines of code. With separate variables each one would have to be written out individually and could not be processed in a loop.",pts:["One identifier holds all the values","Each element is accessed by an index","A loop can process every element using the counter as the index","Far less code is needed, making the program shorter and easier to maintain"]},

/* ---------- 8.3 File handling ---------- */
{t:"8.3",ty:"mcq",m:1,q:"Which mode should be used to add a new record to the end of an existing file without losing the current contents?",o:["FOR APPEND","FOR WRITE","FOR READ","FOR DELETE"],a:0,e:"FOR WRITE would overwrite the whole file."},
{t:"8.3",ty:"txt",m:3,q:"Explain why a program that records high scores must write them to a file rather than only storing them in an array.",a:"An array is stored in RAM, which is volatile, so its contents are lost as soon as the program ends or the computer is switched off. Writing the scores to a file stores them on secondary storage, which is non-volatile, so the data is kept permanently and can be read back in the next time the program is run.",pts:["An array is held in RAM, which is volatile","The data would be lost when the program ends","A file is stored on secondary storage permanently and can be read back later"]},

/* ---------- 9.1 Databases ---------- */
{t:"9.1",ty:"mcq",m:1,q:"Which data type should be used for a telephone number?",o:["Text","Integer","Real","Boolean"],a:0,e:"Phone numbers may begin with 0 or contain a + and spaces, and are never used in calculations, so they are text."},
{t:"9.1",ty:"mcq",m:1,q:"What is a primary key?",o:["A field that uniquely identifies each record in a table","The first field in the table","A field used to sort the records","A password used to open the database"],a:0,e:"The primary key must be unique for every record and cannot be left blank."},
{t:"9.1",ty:"mcq",m:1,q:"Which query lists the Title and Price of all stock costing less than 20, most expensive first?",o:["SELECT Title, Price FROM Stock WHERE Price < 20 ORDER BY Price DESC;","SELECT Title, Price WHERE Price < 20 FROM Stock ORDER BY Price;","SELECT * FROM Stock ORDER BY Price DESC WHERE Price < 20;","FROM Stock SELECT Title, Price WHERE Price < 20;"],a:0,e:"The order is always SELECT, FROM, WHERE, ORDER BY, and DESC gives descending order."},
{t:"9.1",ty:"mcq",m:1,q:"Which query counts how many books are in the Fiction category?",o:["SELECT COUNT(*) FROM Books WHERE Category = 'Fiction';","SELECT SUM(Category) FROM Books;","SELECT COUNT(Fiction) FROM Books;","COUNT Books WHERE Category = Fiction;"],a:0,e:"COUNT(*) counts records, and text values in a WHERE clause go in single quotes."},
{t:"9.1",ty:"txt",m:3,q:"A database table stores products. Explain why ProductCode is a better primary key than ProductName.",a:"A primary key must be unique for every record. Two different products could easily have the same name, for example the same item in two sizes or from two suppliers, so ProductName cannot be guaranteed to be unique. ProductCode is designed to be different for every product, so it uniquely identifies each record. It is also shorter and less likely to be entered inconsistently, for example with different spellings or capitalisation.",pts:["A primary key must uniquely identify each record","Product names could be duplicated","Product codes are guaranteed unique","Codes are shorter or less prone to inconsistent entry"]},

/* ---------- 10.1 Logic ---------- */
{t:"10.1",ty:"mcq",m:1,q:"Which gate gives an output of 1 only when its two inputs are different?",o:["XOR","OR","NAND","AND"],a:0,e:"XOR is exclusive OR: one or the other, but not both."},
{t:"10.1",ty:"mcq",m:1,q:"A NAND gate outputs 0 when:",o:["Both inputs are 1","Both inputs are 0","The inputs are different","Either input is 1"],a:0,e:"NAND is the opposite of AND, so its only 0 is where AND gives 1."},
{t:"10.1",ty:"mcq",m:1,q:"How many rows are needed in a truth table with four inputs?",o:["16","8","4","32"],a:0,e:"2 to the power 4 = 16 rows."},
{t:"10.1",ty:"mcq",m:1,q:"For X = (A OR B) AND NOT C, what is X when A = 0, B = 1, C = 0?",o:["1","0","Cannot be determined","2"],a:0,e:"A OR B = 1, NOT C = 1, and 1 AND 1 = 1."},
{t:"10.1",ty:"mcq",m:1,q:"A NOR gate outputs 1 when:",o:["Both inputs are 0","Both inputs are 1","The inputs are different","At least one input is 1"],a:0,e:"NOR is the opposite of OR, and OR only gives 0 when both inputs are 0."},
{t:"10.1",ty:"txt",m:4,q:"A machine sounds an alarm (X = 1) when the temperature is too high (A = 1) and the lid is open (B = 1), or when the emergency button is pressed (C = 1). Write the logic expression and describe the gates needed.",a:"The expression is X = (A AND B) OR C. An AND gate takes inputs A and B, because both the high temperature and the open lid must be true together. The output of that AND gate becomes one input of an OR gate, and C is the other input, because either that combination or the emergency button alone will sound the alarm. The output of the OR gate is X.",pts:["Correct expression X = (A AND B) OR C","An AND gate with inputs A and B","An OR gate taking the AND output and C","Correct explanation of why AND is used for the pair and OR for the alternative"]},
{t:"10.1",ty:"txt",m:3,q:"Explain how to complete the input columns of a truth table for a three-input logic circuit so that no combination is missed.",a:"There are three inputs, so there are 2 to the power 3 = 8 rows. In the first input column write four 0s followed by four 1s. In the second column write two 0s, two 1s, two 0s and two 1s. In the third column alternate 0 and 1 down the whole column. This halving pattern guarantees that every one of the eight combinations appears exactly once.",pts:["States that 3 inputs need 2^3 = 8 rows","Describes the halving pattern 4/4, 2/2, 1/1","Explains that this guarantees every combination appears once"]}
];
